// ── NODE 1: VALIDATE INPUT & PREPARE BOTH URLs ──────────────────
// Không resolve URL ở đây — chuyển cả 2 sang Node 2 để probe
const body = ($input.first().json.body || $input.first().json.params || $input.first().json);

const issueKey   = (body.issueKey   || '').toUpperCase().trim();
const targetPage = (body.targetPage || 'home').toLowerCase().trim();
const urlOverride = (body.urlOverride || '').trim();

if (!issueKey) {
  return [{ json: { error: '[WebUILocator] Thiếu tham số bắt buộc: issueKey', success: false } }];
}

// Đọc cả 2 URL từ .env — KHÔNG hardcode
const issueKeyTemplate = ($env.ISSUE_KEY_URL || 'https://{issueKey}.trading-test.dnse.com.vn/').replace(/\/$/, '');
const webBaseUrl       = ($env.WEB_BASE_URL   || 'https://dev.trading-test.dnse.com.vn').replace(/\/$/, '');

// issueKeyUrl: thay {issueKey} bằng giá trị thực (lowercase theo subdomain convention)
const issueKeyUrl = issueKeyTemplate.includes('{issueKey}')
  ? issueKeyTemplate.replace('{issueKey}', issueKey.toLowerCase())
  : issueKeyTemplate;

const tradingUsername = $env.TRADING_USERNAME || '';
const tradingPassword = $env.TRADING_PASSWORD || '';

if (!tradingUsername || !tradingPassword) {
  return [{ json: { error: '[WebUILocator] Thiếu TRADING_USERNAME hoặc TRADING_PASSWORD trong .env', success: false } }];
}

// Đọc Playwright browser config từ .env (tôn trọng cấu hình người dùng)
const headless = ($env.HEADLESS || 'false').toLowerCase() === 'true';
const slowMo = parseInt($env.SLOW_MO_MS || '80', 10);
const viewportWidth = parseInt($env.VIEWPORT_WIDTH || '1920', 10);
const viewportHeight = parseInt($env.VIEWPORT_HEIGHT || '1080', 10);
const playwrightTimeout = parseInt($env.PLAYWRIGHT_TIMEOUT_MS || '30000', 10);

const agentWorkspaceDir = ($env.AGENT_WORKSPACE_DIR || process.cwd()).replace(/\/$/, '');
const fixtureDir    = `${agentWorkspaceDir}/workspace/${issueKey}/test/fixtures`;
const screenshotDir = `${agentWorkspaceDir}/workspace/${issueKey}/test/result/screenshots`;
const outputFile    = `${fixtureDir}/locators.json`;

return [{ json: {
  issueKey, targetPage,
  issueKeyUrl,   // URL per-branch (cần probe trước)
  webBaseUrl,    // Fallback luôn sẵn sàng
  urlOverride,
  tradingUsername, tradingPassword,
  headless, slowMo, viewportWidth, viewportHeight, playwrightTimeout,
  agentWorkspaceDir, fixtureDir, screenshotDir, outputFile,
  success: true
}}];

// ── NODE 3: URL PROBE → PLAYWRIGHT LOGIN & DOM DUMP ─────────────
// Bước 1: HTTP HEAD probe ISSUE_KEY_URL (timeout 5s)
//   - alive (2xx/3xx)  → dùng issueKeyUrl
//   - lỗi / 4xx / 5xx  → fallback webBaseUrl
// Bước 2: Playwright mở URL đã chọn, đăng nhập thật, dump locators

const { execSync } = require('child_process');
const https = require('https');
const http  = require('http');
const fs    = require('fs');
const path  = require('path');

const inp = $input.first().json;
const {
  issueKey, targetPage, issueKeyUrl, webBaseUrl, urlOverride,
  tradingUsername, tradingPassword,
  headless = false, slowMo = 80, viewportWidth = 1920, viewportHeight = 1080, playwrightTimeout = 30000,
  agentWorkspaceDir, fixtureDir, screenshotDir, outputFile
} = inp;

[fixtureDir, screenshotDir].forEach(d => {
  if (!fs.existsSync(d)) fs.mkdirSync(d, { recursive: true });
});

// ── Probe helper: HTTP HEAD request với timeout 5s ───────────────
function probeUrl(targetUrl) {
  return new Promise((resolve) => {
    try {
      const parsed = new URL(targetUrl);
      const lib = parsed.protocol === 'https:' ? https : http;
      const req = lib.request(
        { hostname: parsed.hostname, port: parsed.port || (parsed.protocol === 'https:' ? 443 : 80),
          path: parsed.pathname || '/', method: 'HEAD',
          timeout: 5000,
          rejectUnauthorized: false  // UAT thường dùng self-signed cert
        },
        (res) => resolve({ ok: res.statusCode < 400, status: res.statusCode })
      );
      req.on('error',   () => resolve({ ok: false, status: 0, reason: 'connection_error' }));
      req.on('timeout', () => { req.destroy(); resolve({ ok: false, status: 0, reason: 'timeout' }); });
      req.end();
    } catch (err) {
      resolve({ ok: false, status: 0, reason: err.message });
    }
  });
}

// ── Resolve URL: probe ISSUE_KEY_URL → fallback WEB_BASE_URL ─────
let resolvedUrl, urlSource, probeStatus;

if (urlOverride) {
  resolvedUrl = urlOverride.replace(/\/$/, '');
  urlSource   = 'urlOverride';
  probeStatus = { ok: true, status: 'skipped' };
} else {
  probeStatus = await probeUrl(issueKeyUrl);
  if (probeStatus.ok) {
    resolvedUrl = issueKeyUrl;
    urlSource   = 'ISSUE_KEY_URL';
  } else {
    resolvedUrl = webBaseUrl;
    urlSource   = 'WEB_BASE_URL (fallback)';
  }
}

const loginUrl  = `${resolvedUrl}/login`;
const targetUrl = targetPage === 'home' ? resolvedUrl : `${resolvedUrl}/${targetPage}`;
const screenshotBefore = `${screenshotDir}/${targetPage}-before-login.png`;
const screenshotAfter  = `${screenshotDir}/${targetPage}-after-login.png`;

// ── Playwright script ─────────────────────────────────────────────
const script = `
const { chromium } = require('playwright');
const fs = require('fs');
(async () => {
  const browser = await chromium.launch({ headless: ${headless}, slowMo: ${slowMo} });
  const ctx  = await browser.newContext({ viewport: { width: ${viewportWidth}, height: ${viewportHeight} }, locale: 'vi-VN' });
  const page = await ctx.newPage();
  const result = {
    issueKey: ${JSON.stringify(issueKey)}, targetPage: ${JSON.stringify(targetPage)},
    resolvedUrl: ${JSON.stringify(resolvedUrl)}, urlSource: ${JSON.stringify(urlSource)},
    issueKeyUrl: ${JSON.stringify(issueKeyUrl)}, webBaseUrl: ${JSON.stringify(webBaseUrl)},
    probeStatus: ${JSON.stringify(probeStatus)},
    loginSuccess: false, locators: {}, errors: [],
    capturedAt: new Date().toISOString()
  };
  try {
    await page.goto(${JSON.stringify(loginUrl)}, { waitUntil: 'domcontentloaded', timeout: ${playwrightTimeout} });
    await page.screenshot({ path: ${JSON.stringify(screenshotBefore)} });

    const loginCandidates = [
      { key: 'username_input', tries: ['getByLabel:Tên đăng nhập','getByLabel:Username','getByPlaceholder:Tên đăng nhập','locator:input[type=text]'] },
      { key: 'password_input', tries: ['getByLabel:Mật khẩu','getByLabel:Password','locator:input[type=password]'] },
      { key: 'login_button',   tries: ['getByRole:button|Đăng nhập','getByRole:button|Login','locator:button[type=submit]'] }
    ];
    const loginLoc = {};
    for (const cand of loginCandidates) {
      for (const t of cand.tries) {
        const [method, ...rest] = t.split(':');
        const arg = rest.join(':');
        try {
          let loc;
          if (method === 'getByRole') { const [r,n] = arg.split('|'); loc = page.getByRole(r, { name: n }); }
          else if (method === 'getByLabel') { loc = page.getByLabel(arg); }
          else if (method === 'getByPlaceholder') { loc = page.getByPlaceholder(arg); }
          else { loc = page.locator(arg); }
          const c = await loc.count();
          if (c > 0) {
            const el = loc.first();
            const attrs = await el.evaluate(n => ({
              tag: n.tagName.toLowerCase(), role: n.getAttribute('role'),
              ariaLabel: n.getAttribute('aria-label'), placeholder: n.getAttribute('placeholder'),
              name: n.getAttribute('name'), type: n.getAttribute('type')
            })).catch(() => ({}));
            let playwright_code;
            if (method === 'getByRole') { const [r,n]=arg.split('|'); playwright_code='page.get_by_role("'+r+'", name="'+n+'")';
            } else if (method==='getByLabel') playwright_code='page.get_by_label("'+arg+'")';
            else if (method==='getByPlaceholder') playwright_code='page.get_by_placeholder("'+arg+'")';
            else playwright_code='page.locator("'+arg+'")';
            loginLoc[cand.key] = { method, arg, playwright_code, ...attrs,
              isVisible: await el.isVisible().catch(()=>false),
              isEnabled: await el.isEnabled().catch(()=>false) };
            break;
          }
        } catch(_){}
      }
    }
    result.locators.login = loginLoc;

    if (loginLoc.username_input && loginLoc.password_input && loginLoc.login_button) {
      const getEl = (info) => {
        if (info.method==='getByRole') { const [r,n]=info.arg.split('|'); return page.getByRole(r,{name:n}); }
        if (info.method==='getByLabel') return page.getByLabel(info.arg);
        if (info.method==='getByPlaceholder') return page.getByPlaceholder(info.arg);
        return page.locator(info.arg);
      };
      await getEl(loginLoc.username_input).fill(${JSON.stringify(tradingUsername)});
      await getEl(loginLoc.password_input).fill(${JSON.stringify(tradingPassword)});
      await getEl(loginLoc.login_button).click();
      await page.waitForLoadState('networkidle', { timeout: 15000 }).catch(()=>{});
      result.loginSuccess = true;
    } else {
      result.errors.push('Không tìm đủ locator login form (username/password/button)');
    }
    await page.screenshot({ path: ${JSON.stringify(screenshotAfter)} });

    if (result.loginSuccess && ${JSON.stringify(targetUrl)} !== ${JSON.stringify(loginUrl)}) {
      await page.goto(${JSON.stringify(targetUrl)}, { waitUntil: 'domcontentloaded', timeout: ${playwrightTimeout} });
      await page.waitForTimeout(1500);
    }
    const pageElems = await page.evaluate(() => {
      const out = [];
      ['button','input','select','textarea','[role=tab]','[role=dialog]','[role=alert]','[role=heading]','[data-testid]'].forEach(sel => {
        document.querySelectorAll(sel).forEach(el => {
          const role = el.getAttribute('role') || el.tagName.toLowerCase();
          const ariaLabel = el.getAttribute('aria-label')||'';
          const placeholder = el.getAttribute('placeholder')||'';
          const name = el.getAttribute('name')||'';
          const testId = el.getAttribute('data-testid')||'';
          const innerText = (el.innerText||'').trim().slice(0,80);
          if (!ariaLabel&&!placeholder&&!name&&!testId&&!innerText) return;
          let playwright_code = '';
          if (role&&innerText) playwright_code='page.get_by_role("'+role+'", name="'+innerText.slice(0,40)+'")';
          else if (ariaLabel) playwright_code='page.get_by_label("'+ariaLabel+'")';
          else if (placeholder) playwright_code='page.get_by_placeholder("'+placeholder+'")';
          else if (testId) playwright_code='page.get_by_test_id("'+testId+'")';
          else if (name) playwright_code='page.locator("[name=\''+name+'\']")'; 
          if (playwright_code) out.push({ tag:el.tagName.toLowerCase(), role, ariaLabel, placeholder, name, testId, innerText, playwright_code, isVisible: el.offsetParent!==null });
        });
      });
      return out;
    });
    result.locators[${JSON.stringify(targetPage)}] = pageElems.filter(e=>e.isVisible).slice(0,80);
  } catch(e) {
    result.errors.push(e.message);
  } finally {
    await browser.close();
  }
  fs.writeFileSync(${JSON.stringify(outputFile)}, JSON.stringify(result, null, 2), 'utf-8');
  console.log(JSON.stringify({ success: result.loginSuccess, locatorCount: (result.locators[${JSON.stringify(targetPage)}]||[]).length, urlSource: result.urlSource }));
})();
`;

const tmpScript = path.join(fixtureDir, `_pw_disc_${Date.now()}.cjs`);
fs.writeFileSync(tmpScript, script, 'utf-8');

let stdout='', stderr='', exitCode=0, locatorsData=null;
try {
  stdout = execSync(`node "${tmpScript}"`, { cwd: agentWorkspaceDir, encoding: 'utf-8', timeout: 120000 });
  if (fs.existsSync(outputFile)) locatorsData = JSON.parse(fs.readFileSync(outputFile, 'utf-8'));
} catch(e) { stderr=e.stderr||e.message; exitCode=e.status||1; }
finally { try { fs.unlinkSync(tmpScript); } catch(_){} }

return [{ json: {
  issueKey, targetPage,
  issueKeyUrl, webBaseUrl,
  resolvedUrl, urlSource,
  probeStatus,
  loginUrl, targetUrl,
  outputFile,
  screenshotBefore, screenshotAfter,
  stdout, stderr, exitCode,
  loginSuccess: locatorsData?.loginSuccess || false,
  locatorCount: (locatorsData?.locators?.[targetPage]||[]).length,
  locatorsData,
  success: exitCode===0 && (locatorsData?.loginSuccess||false)
}}];
